        PLOT.slider(ctl,{label:"Constant C",min:-3,max:3,step:0.5,value:0,fmt:v=>v.toFixed(1),oninput:v=>{ C=v; main.update(x=>S[key].F(x)+C); H.move(x0); draw(); }});
